-- DeAltura: catálogo editable desde el admin (cafés, orígenes, fincas), fotos en Supabase Storage,
-- compras ligadas a un café, y fecha exacta en los gastos.
-- Correr en Supabase → SQL Editor después de 0004_inventory.sql.

create table if not exists products (
  id text primary key,
  slug text not null unique,
  active boolean not null default true,
  sort int not null default 0,
  data jsonb not null,               -- el café completo (nombre, notas por tueste, ficha, formatos, fotos...)
  updated_at timestamptz not null default now()
);

create table if not exists origins (
  id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

create table if not exists farms (
  id text primary key,
  product_id text references products(id) on delete set null,
  published boolean not null default false,
  sort int not null default 0,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table products enable row level security;
alter table origins enable row level security;
alter table farms enable row level security;
grant select, insert, update, delete on products, origins, farms to service_role;
revoke all on products, origins, farms from anon, authenticated;

-- Compras: a qué café del catálogo corresponden
alter table green_lots add column if not exists product_id text references products(id) on delete set null;

-- Gastos: fecha exacta (el mes se sigue guardando para agrupar)
alter table expenses add column if not exists spent_on date;
update expenses set spent_on = (month || '-01')::date where spent_on is null;

