-- Las compras que ya existían son del café de Venezuela
update green_lots set product_id = 'prd_ven_scm' where product_id is null and exists (select 1 from products where id = 'prd_ven_scm');

-- Fotos subidas desde el admin: bucket público "catalog" (solo el servidor sube; cualquiera puede verlas)
do $$
begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public) values ('catalog', 'catalog', true)
    on conflict (id) do update set public = true;
  end if;
end $$;
